{"implementation":"def solve(case):
    payload = case.get('payload')
    if not payload: raise ValueError("Missing payload")
    text = payload.get('text')
    passes = payload.get('passes')
    max_rounds = payload.get('max_rounds')
    if text is None or passes is None or max_rounds is None:
        raise ValueError("Missing required fields")
    if not isinstance(text, str): raise ValueError("text must be string")
    if not isinstance(passes, list): raise ValueError("passes must be list")
    for p in passes:
        if not isinstance(p, dict) or 'name' not in p or 'old' not in p or 'new' not in p:
            raise ValueError("Each pass must have name, old, new")
    if not isinstance(max_rounds, int) or max_rounds < 1:
        raise ValueError("max_rounds must be positive integer")
    current = text
    trace = []
    for round in range(max_rounds):
        changed_in_round = False
        for p in passes:
            old = p['old']
            new = p['new']
            if old in current:
                idx = current.find(old)
                current = current[:idx] + new + current[idx+len(old):]
                trace.append(p['name'])
                changed_in_round = True
        if not changed_in_round:
            return {"artifact": current, "trace": trace, "fixed_point": True}
    return {"artifact": current, "trace": trace, "fixed_point": False}"}
